void transpose(int n, double* A, double* B) {
    // Blocked (tiled) transpose for cache locality
    const int blockSize = 32;
    for (int i = 0; i < n; i += blockSize) {
        for (int j = 0; j < n; j += blockSize) {
            for (int ii = i; ii < i + blockSize && ii < n; ++ii) {
